<script lang="ts">
 import { page } from '$app/state'; import { onMount } from 'svelte'; import PageHeader from '$lib/components/PageHeader.svelte'; import { listTasks } from '$lib/api/tasks'; import { listMilestones } from '$lib/api/milestones'; import type { Milestone, TaskView } from '$lib/api/types';
 const projectKey=$derived(String(page.params.projectKey ?? '')); let tasks=$state<TaskView[]>([]), milestones=$state<Milestone[]>([]), loading=$state(true), errorMessage=$state(''); onMount(async()=>{try{const[t,m]=await Promise.all([listTasks(projectKey,1,100),listMilestones(projectKey)]);tasks=t.data.items;milestones=m.data.items}catch(e){errorMessage=e instanceof Error?e.message:'时间线加载失败'}finally{loading=false}}); const events=$derived([...tasks.map(t=>({date:t.due_at||t.created_at,label:t.title,key:t.task_key,type:'任务'})),...milestones.filter(m=>m.due_date).map(m=>({date:`${m.due_date}T00:00:00Z`,label:m.name,key:m.id,type:'里程碑'}))].sort((a,b)=>a.date.localeCompare(b.date)));
</script>
<PageHeader title="时间线" eyebrow="Timeline" description="按时间顺序观察任务截止时间、创建节奏和里程碑节点。" />
{#if errorMessage}<div class="workspace-card error-state">{errorMessage}</div>{/if}{#if loading}<section class="workspace-card state-box">正在加载时间线…</section>{:else}<section class="workspace-card timeline">{#each events as event}<div class="event"><div class="event-date">{new Date(event.date).toLocaleDateString('zh-CN')}</div><div class="event-line"><span></span></div><div class="event-content"><small>{event.type}</small><a href={event.type==='任务'?`/tasks/${event.key}`:`/projects/${projectKey}/milestones`}><strong>{event.label}</strong></a><p>{event.type==='任务'?'任务创建或截止节点':'项目阶段目标'}</p></div></div>{:else}<p class="empty-inline">当前项目还没有时间线数据。</p>{/each}</section>{/if}
<style>.timeline{display:grid;gap:0}.event{display:grid;grid-template-columns:120px 22px 1fr;gap:12px;min-height:78px}.event-date{padding-top:4px;color:var(--color-text-muted);font-size:13px;text-align:right}.event-line{position:relative}.event-line:before{content:'';position:absolute;top:0;bottom:0;left:10px;border-left:1px solid var(--color-border-strong)}.event-line span{position:absolute;top:6px;left:5px;width:12px;height:12px;border:3px solid var(--color-primary);border-radius:50%;background:#fff}.event-content{display:grid;gap:4px;padding-bottom:18px}.event-content small{color:var(--color-primary);font-size:11px;font-weight:800}.event-content p{margin:0;color:var(--color-text-muted);font-size:13px}.error-state{color:var(--color-danger);margin-bottom:16px}.state-box{text-align:center;color:var(--color-text-muted)}@media(max-width:560px){.event{grid-template-columns:82px 18px 1fr}.event-date{font-size:11px}}</style>
